1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface ScenarioOutput {
41	  results: unknown[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number | undefined> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type] ?? 0;
60	
61	const CURSE_SURCHARGE_RATE = 0.5;
62	const HIGH_ENCHANTMENT_LEVEL = 5;
63	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
64	
65	const isCursed = (item: Item): boolean => item.cursed === true;
66	const isHighlyEnchanted = (item: Item): boolean =>
67	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
68	
69	/** Item-specific modifiers apply to the base premium of the affected item only. */
70	const itemSurchargesOf = (item: Item): number => {
71	  const basePremium = basePremiumOfType(item.type);
72	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
73	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
74	    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
75	    : 0;
76	  return curseSurcharge + highEnchantmentSurcharge;
77	};
78	
79	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
80	const COMPONENT_BLOCK_SIZE = 3;
81	const COMPONENT_BLOCK_PREMIUM = 60;
82	
83	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
84	
85	const countByType = (items: Item[]): Map<string, number> => {
86	  const counts = new Map<string, number>();
87	  for (const item of items) {
88	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
89	  }
90	  return counts;
91	};
92	
93	/**
94	 * Items of one type are normally priced individually. The exception is
95	 * components: exactly 3 alike ones form a "building block" priced as a unit.
96	 */
97	const typeGroupPremium = (type: string, count: number): number =>
98	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
99	    ? COMPONENT_BLOCK_PREMIUM
100	    : count * basePremiumOfType(type);
101	
102	const policyBasePremiumOf = (items: Item[]): number =>
103	  [...countByType(items)].reduce(
104	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
105	    0,
106	  );
107	
108	const isLongStanding = (customer: Customer): boolean =>
109	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
110	
111	/** What the policy-wide modifiers are judged against, beyond the items themselves. */
112	interface QuoteContext {
113	  customer: Customer;
114	  isFollowUpContract: boolean;
115	}
116	
117	/**
118	 * Policy-wide modifiers are signed rates charged against the policy base
119	 * premium: surcharges positive, discounts negative.
120	 */
121	const policyModifierRateFor = (context: QuoteContext): number =>
122	  INITIAL_ASSESSMENT_SURCHARGE_RATE -
123	  (isLongStanding(context.customer) ? LOYALTY_DISCOUNT_RATE : 0) -
124	  (context.isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
125	
126	const itemSurchargesOfPolicy = (items: Item[]): number =>
127	  items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
128	
129	/** Kept as an exact fraction — only the final premium is rounded. */
130	const premiumBeforeRounding = (items: Item[], context: QuoteContext): number => {
131	  const policyBasePremium = policyBasePremiumOf(items);
132	  const policyModifiers = policyBasePremium * policyModifierRateFor(context);
133	  return policyBasePremium + itemSurchargesOfPolicy(items) + policyModifiers + PROCESSING_FEE;
134	};
135	
136	/** Rounded up, in the MHPCO's favour. */
137	const finalPremiumFor = (items: Item[], context: QuoteContext): number =>
138	  Math.ceil(premiumBeforeRounding(items, context));
139	
140	const INSURANCE_VALUES: Record<string, number | undefined> = {
141	  sword: 1000,
142	  amulet: 600,
143	  staff: 800,
144	  potion: 400,
145	  rune: 250,
146	  moonstone: 250,
147	};
148	
149	const DEDUCTIBLE = 100;
150	const CAP_MULTIPLIER = 2;
151	
152	const insuranceSumOf = (items: Item[]): number =>
153	  items.reduce((sum, item) => sum + (INSURANCE_VALUES[item.type] ?? 0), 0);
154	
155	/** A policy created by a quote step, tracked so later claims can draw on it. */
156	interface Policy {
157	  items: Item[];
158	  remainingCap: number;
159	}
160	
161	/** The most a policy will ever pay out, across all claims against it. */
162	const capFor = (items: Item[]): number => insuranceSumOf(items) * CAP_MULTIPLIER;
163	
164	const openPolicyFor = (items: Item[]): Policy => ({ items, remainingCap: capFor(items) });
165	
166	const CLAIM_HIGH_ENCHANTMENT_LEVEL = 8;
167	const CLAIM_HIGH_ENCHANTMENT_RATE = 0.5;
168	
169	const isHighlyEnchantedForClaims = (item: Item | undefined): boolean =>
170	  (item?.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_LEVEL;
171	
172	const payoutForDamage = (damage: Damage, item: Item | undefined): number => {
173	  const reimbursed = isHighlyEnchantedForClaims(item)
174	    ? damage.amount * CLAIM_HIGH_ENCHANTMENT_RATE
175	    : damage.amount;
176	  return reimbursed - DEDUCTIBLE;
177	};
178	
179	interface Settlement {
180	  payout: number;
181	  remainingCap: number;
182	}
183	
184	/**
185	 * Draws against the policy's remaining cap, which it depletes.
186	 * Rounded down, in the MHPCO's favour.
187	 */
188	const settleClaim = (step: ClaimStep, policy: Policy): Settlement => {
189	  const claimed = step.incident.damages.reduce(
190	    (sum, damage) =>
191	      sum + payoutForDamage(damage, policy.items.find((item) => item.type === damage.itemType)),
192	    0,
193	  );
194	  const payout = Math.floor(Math.min(claimed, policy.remainingCap));
195	
196	  policy.remainingCap -= payout;
197	  return { payout, remainingCap: policy.remainingCap };
198	};
199	
200	const policyReferencedBy = (step: ClaimStep, policies: Map<number, Policy>): Policy => {
201	  const policy = policies.get(step.policy);
202	  if (policy === undefined) {
203	    throw new Error(`claim references unknown policy at step ${String(step.policy)}`);
204	  }
205	  return policy;
206	};
207	
208	export const runScenario = (scenario: Scenario): ScenarioOutput => {
209	  const policies = new Map<number, Policy>();
210	
211	  const results = scenario.steps.map((step, stepIndex) => {
212	    if (step.op === "claim") {
213	      return settleClaim(step, policyReferencedBy(step, policies));
214	    }
215	
216	    // Every quote but the first is a follow-up contract for this customer.
217	    const isFollowUpContract = policies.size > 0;
218	    policies.set(stepIndex, openPolicyFor(step.items));
219	
220	    return {
221	      premium: finalPremiumFor(step.items, { customer: scenario.customer, isFollowUpContract }),
222	    };
223	  });
224	
225	  return { results };
226	};
