/**
 * Unrelated to the high-enchantment premium surcharge: that one is judged
 * against HIGH_ENCHANTMENT_LEVEL, this one against its own, higher threshold.
 */
const qualifiesForHalfReimbursement = (insuredItem: Item): boolean =>
  (insuredItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_LEVEL;

/** The share of the damage the MHPCO reimburses, before the deductible. */
const reimbursementRateFor = (insuredItem: Item): number =>
  qualifiesForHalfReimbursement(insuredItem) ? CLAIM_HIGH_ENCHANTMENT_RATE : 1;

const payoutForDamage = (damage: Damage, insuredItem: Item): number =>
  damage.amount * reimbursementRateFor(insuredItem) - DEDUCTIBLE;

const insuredItemFor = (damage: Damage, policy: Policy): Item => {
  const insuredItem = policy.items.find((item) => item.type === damage.itemType);
  if (insuredItem === undefined) {
    throw new Error(`claim references uninsured item type ${damage.itemType}`);
  }
  return insuredItem;
};

